<?php require __DIR__.'/config/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$db->pdo()->prepare('INSERT INTO vocabulary(word,meaning,example_sentence) VALUES(?,?,?)');$s->execute(array(trim($_POST['word']),trim($_POST['meaning']),trim($_POST['example_sentence']))); }
$rows=$db->pdo()->query('SELECT * FROM vocabulary ORDER BY id DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@3.4.1/dist/css/bootstrap.min.css"></head><body><div class="container"><p><a href="index.php">← Dashboard</a></p><h1>Vocabulary</h1><form method="post" class="row"><div class="col-sm-3"><input class="form-control" name="word" placeholder="Word" required></div><div class="col-sm-3"><input class="form-control" name="meaning" placeholder="Meaning" required></div><div class="col-sm-4"><input class="form-control" name="example_sentence" placeholder="Example"></div><div class="col-sm-2"><button class="btn btn-primary">Add</button></div></form><hr><table class="table"><tr><th>Word</th><th>Meaning</th><th>Example</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['word'])?></td><td><?=e($r['meaning'])?></td><td><?=e($r['example_sentence'])?></td></tr><?php endforeach;?></table></div></body></html>
